(function() {
    'use strict';

    // Zero Step: Run only in the first tab
    if (window.opener || window !== window.top) return;

    // First Step: Ensure it runs only on the main page
    const mainPage = 'http://www.drtorkzadeh.com/';
    if (window.location.href !== mainPage) return;

    // Second Step: Check the time
    function checkTime() {
        const now = new Date();
        const currentHour = now.getHours();
        const currentMinute = now.getMinutes();
        const currentTime = currentHour * 100 + currentMinute;

        if (currentTime >= 2230 || currentTime < 330) {
            return true;
        } else {
            console.log('Waiting for the desired time...');
            setTimeout(checkTime, 60000); // Check every minute
            return false;
        }
    }

    // Third Step: Check for the specific text and reload the page
    function checkTextAndReload() {
        const textToFind = 'رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است';
        const textElement = document.body.innerText.includes(textToFind);

        if (textElement) {
            console.log('Text found, reloading in 5 seconds...');
            setTimeout(() => location.reload(), 5000);
        } else {
            switchToNextTab();
        }
    }

    // Fourth Step: Switch to the next tab
    function switchToNextTab() {
        // Open the second tab
        const secondTabUrl = 'http://www.drtorkzadeh.com/second-page'; // Replace with the actual URL
        const secondTab = window.open(secondTabUrl, '_blank');

        // Wait for the second tab to load and then send a message to it
        secondTab.onload = () => {
            secondTab.postMessage('DOMContentLoaded', secondTabUrl);
        };
    }

    // Fifth Step: Click the submit button in the second tab
    function clickSubmitButton() {
        const submitButton = document.querySelector('input[type="submit"][id="submit"]');
        if (submitButton) {
            submitButton.click();
            console.log('Submit button clicked, stopping the script.');
            localStorage.removeItem('clickSubmitButton');
        } else {
            console.log('Submit button not found, retrying in 2 seconds...');
            setTimeout(clickSubmitButton, 2000);
        }
    }

    // Listen for messages from the main tab
    if (window.name === 'secondTab') {
        window.addEventListener('message', (event) => {
            if (event.data === 'DOMContentLoaded' && event.origin === 'http://www.drtorkzadeh.com') {
                localStorage.setItem('clickSubmitButton', 'true');
                clickSubmitButton();
            }
        });

        // Also check localStorage for the message
        setInterval(() => {
            if (localStorage.getItem('clickSubmitButton') === 'true') {
                clickSubmitButton();
            }
        }, 1000); // Check every second
    }

    // Main function to start the process
    function startProcess() {
        if (checkTime()) {
            checkTextAndReload();
        }
    }

    // Start the process
    startProcess();
})();
```

