```java
package com.example.photoapp;

import android.os.Bundle;
import android.view.View;
import android.widget.AdapterView;
import android.widget.Button;
import android.widget.ListView;
import android.widget.SearchView;
import android.widget.Toast;
import androidx.appcompat.app.AppCompatActivity;
import com.android.volley.Request;
import com.android.volley.RequestQueue;
import com.android.volley.Response;
import com.android.volley.VolleyError;
import com.android.volley.toolbox.JsonArrayRequest;
import com.android.volley.toolbox.Volley;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.List;

public class MainActivity extends AppCompatActivity {

    private SearchView searchView;
    private ListView photoList;
    private Button submitButton;
    private Button adminPanelButton;
    private List<Photo> photoListItems;
    private PhotoAdapter photoAdapter;
    private RequestQueue requestQueue;
    private int currentPage = 1;
    private int pageSize = 10;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        searchView = findViewById(R.id.search_view);
        photoList = findViewById(R.id.photo_list);
        submitButton = findViewById(R.id.submit_button);
        adminPanelButton = findViewById(R.id.admin_panel_button);

        photoListItems = new ArrayList<>();
        photoAdapter = new PhotoAdapter(this, photoListItems);
        photoList.setAdapter(photoAdapter);

        requestQueue = Volley.newRequestQueue(this);

        loadPhotos(currentPage, pageSize);

        searchView.setOnQueryTextListener(new SearchView.OnQueryTextListener() {
            @Override
            public boolean onQueryTextSubmit(String query) {
                searchPhotos(query);
                return true;
            }

            @Override
            public boolean onQueryTextChange(String newText) {
                return false;
            }
        });

        submitButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                openSubmitPhotoDialog();
            }
        });

        adminPanelButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                openAdminPanel();
            }
        });

        photoList.setOnItemClickListener(new AdapterView.OnItemClickListener() {
            @Override
            public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
                Photo selectedPhoto = photoListItems.get(position);
                // Handle photo click (e.g., show details)
                Toast.makeText(MainActivity.this, "Selected: " + selectedPhoto.getName(), Toast.LENGTH_SHORT).show();
            }
        });

        photoList.setOnScrollListener(new AbsListView.OnScrollListener() {
            @Override
            public void onScrollStateChanged(AbsListView view, int scrollState) {
                if (scrollState == AbsListView.OnScrollListener.SCROLL_STATE_IDLE && !view.canScrollVertically(1)) {
                    currentPage++;
                    loadPhotos(currentPage, pageSize);
                }
            }

            @Override
            public void onScroll(AbsListView view, int firstVisibleItem, int visibleItemCount, int totalItemCount) {
            }
        });
    }

    private void loadPhotos(int page, int pageSize) {
        String url = "http://your_flask_server_address/list?page=" + page + "&page_size=" + pageSize;
        JsonArrayRequest request = new JsonArrayRequest(Request.Method.GET, url, null,
            new Response.Listener<JSONArray>() {
                @Override
                public void onResponse(JSONArray response) {
                    for (int i = 0; i < response.length(); i++) {
                        try {
                            JSONObject jsonObject = response.getJSONObject(i);
                            Photo photo = new Photo(
                                jsonObject.getString("name"),
                                jsonObject.getDouble("price"),
                                jsonObject.getString("description"),
                                jsonObject.getString("photo_url")
                            );
                            photoListItems.add(photo);
                        } catch (JSONException e) {
                            e.printStackTrace();
                        }
                    }
                    photoAdapter.notifyDataSetChanged();
                }
            },
            new Response.ErrorListener() {
                @Override
                public void onErrorResponse(VolleyError error) {
                    Toast.makeText(MainActivity.this, "Error loading photos", Toast.LENGTH_SHORT).show();
                }
            }
        );

        requestQueue.add(request);
    }

    private void searchPhotos(String query) {
        String url = "http://your_flask_server_address/search?query=" + query;
        JsonArrayRequest request = new JsonArrayRequest(Request.Method.GET, url, null,
            new Response.Listener<JSONArray>() {
                @Override
                public void onResponse(JSONArray response) {
                    photoListItems.clear();
                    for (int i = 0; i < response.length(); i++) {
                        try {
                            JSONObject jsonObject = response.getJSONObject(i);
                            Photo photo = new Photo(
                                jsonObject.getString("name"),
                                jsonObject.getDouble("price"),
                                jsonObject.getString("description"),
                                jsonObject.getString("photo_url")
                            );
                            photoListItems.add(photo);
                        } catch (JSONException e) {
                            e.printStackTrace();
