```csharp
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.Formats.Png;
using SixLabors.ImageSharp.Processing;

public class ImageCompressor
{
    public static byte[] CompressImage(Image image, ImageFormat format, int quality, int? width = null, int? height = null)
    {
        if (image == null)
            throw new ArgumentNullException(nameof(image));

        if (format != ImageFormat.Png && format != ImageFormat.Jpeg)
            throw new ArgumentException("Unsupported image format. Only PNG and JPEG are supported.", nameof(format));

        if (quality < 0 || quality > 100)
            throw new ArgumentOutOfRangeException(nameof(quality), "Quality must be between 0 and 100.");

        using (var ms = new MemoryStream())
        {
            if (format == ImageFormat.Jpeg)
            {
                // Set up JPEG encoder parameters
                var encoderParameters = new EncoderParameters(1);
                encoderParameters.Param[0] = new EncoderParameter(Encoder.Quality, quality);

                // Get the JPEG encoder
                var jpegEncoder = GetEncoder(ImageFormat.Jpeg);

                // Save the image with the specified quality
                image.Save(ms, jpegEncoder, encoderParameters);
            }
            else
            {
                // Convert the System.Drawing.Image to a SixLabors.ImageSharp.Image
                using (var imgSharp = Image.Load(image, out var formatIgnored))
                {
                    // Resize the image if width or height is provided
                    if (width.HasValue || height.HasValue)
                    {
                        imgSharp.Mutate(x => x.Resize(width ?? imgSharp.Width, height ?? imgSharp.Height));
                    }

                    // Set up PNG encoder parameters
                    var pngEncoder = new PngEncoder
                    {
                        CompressionLevel = qualityToCompressionLevel(quality)
                    };

                    // Save the image in PNG format
                    imgSharp.SaveAsPng(ms, pngEncoder);
                }
            }

            return ms.ToArray();
        }
    }

    private static ImageCodecInfo GetEncoder(ImageFormat format)
    {
        foreach (var codec in ImageCodecInfo.GetImageDecoders())
        {
            if (codec.FormatID == format.Guid)
                return codec;
        }
        throw new ArgumentException("Unsupported image format.", nameof(format));
    }

    private static PngCompressionLevel qualityToCompressionLevel(int quality)
    {
        // Map quality to compression level
        if (quality >= 90)
            return PngCompressionLevel.Level9;
        else if (quality >= 80)
            return PngCompressionLevel.Level8;
        else if (quality >= 70)
            return PngCompressionLevel.Level7;
        else if (quality >= 60)
            return PngCompressionLevel.Level6;
        else if (quality >= 50)
            return PngCompressionLevel.Level5;
        else if (quality >= 40)
            return PngCompressionLevel.Level4;
        else if (quality >= 30)
            return PngCompressionLevel.Level3;
        else if (quality >= 20)
            return PngCompressionLevel.Level2;
        else
            return PngCompressionLevel.Level1;
    }
}

// Usage Example
class Program
{
    static void Main()
    {
        // Load an image
        Image image = Image.FromFile("input.jpg");

        // Compress the image to JPEG with 80% quality
        byte[] compressedJpeg = ImageCompressor.CompressImage(image, ImageFormat.Jpeg, 80);
        File.WriteAllBytes("output_compressed.jpg", compressedJpeg);

        // Compress the image to PNG with 80% quality and resize to 500x500
        byte[] compressedPng = ImageCompressor.CompressImage(image, ImageFormat.Png, 80, 500, 500);
        File.WriteAllBytes("output_compressed.png", compressedPng);
    }
}
